import React from "react";

class MiLista extends React.Component {
    incidencias=["Proyecto averia", "Ordenador no enciende", "Impresora sin conexion" , "WIFI no disponible"]

    render(){
    return(
        <div ClassName='lista'>
            <ul>
                {
                    this.incidencias.map((i)=> (
                        <li>{i}</li>

                    ))

                }
            </ul>
        </div>
    );
}
}
export default MiLista;
